                                                                                                                                                                                                       
  CREATE TABLE "CHECK_RECORD"                                                                                                                                                               
   (	"RECORD_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                 
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"UPDATED_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                  
	"REMARK" NVARCHAR2(512),                                                                                                                                                                              
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                   
	"DEVICE_ID" NUMBER NOT NULL ENABLE,                                                                                                                                                                   
	"DEVICE_NAME" NVARCHAR2(512),                                                                                                                                                                         
	"FORM_ID" NVARCHAR2(512) NOT NULL ENABLE,                                                                                                                                                             
	"FORM_NAME" NVARCHAR2(512) NOT NULL ENABLE,                                                                                                                                                           
	"FAB_ID" NUMBER(20,0),                                                                                                                                                                                
	"FAB_NAME" NVARCHAR2(512) NOT NULL ENABLE,                                                                                                                                                            
	"EXT_ORG_ID" NUMBER(20,0),                                                                                                                                                                            
	"EXT_ORG_NAME" NVARCHAR2(32),                                                                                                                                                                         
	"LINE_ID" NUMBER(20,0),                                                                                                                                                                               
	"LINE_NAME" NVARCHAR2(512) NOT NULL ENABLE,                                                                                                                                                           
	"AREA_ID" NUMBER(20,0),                                                                                                                                                                               
	"AREA_NAME" NVARCHAR2(512) NOT NULL ENABLE,                                                                                                                                                           
	"STATUS" NVARCHAR2(20),                                                                                                                                                                               
	"CHECK_USER_ID" NUMBER(20,0),                                                                                                                                                                         
	"CHECK_USER_JOB_NUMBER" NVARCHAR2(20),                                                                                                                                                                
	"CHECK_USER_NAME" NVARCHAR2(50),                                                                                                                                                                      
	"CHECK_DATE" DATE,                                                                                                                                                                                    
	"RESULT" NVARCHAR2(20),                                                                                                                                                                               
	"SORT_NUM" NUMBER(20,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                    
	"CHECK_EXPIRE_DATE" DATE,                                                                                                                                                                             
	"DEVICE_CODE" NVARCHAR2(200),                                                                                                                                                                         
	"IP" NVARCHAR2(64),                                                                                                                                                                                   
	"CATEGORY_FIRST_CODE" NVARCHAR2(50),                                                                                                                                                                  
	"CATEGORY_FIRST_NAME" NVARCHAR2(100),                                                                                                                                                                 
	"FORM_CLASSIFY_CODE" NVARCHAR2(100),                                                                                                                                                                  
	"FORM_CLASSIFY_NAME" NVARCHAR2(128),                                                                                                                                                                  
	"FORM_CLASSIFY_ID" NUMBER,                                                                                                                                                                            
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                         
	"DEPT_ID" NUMBER,                                                                                                                                                                                     
	"DEPT_NAME" NVARCHAR2(64),                                                                                                                                                                            
	"FIRST_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                        
	"OBJECT_ID" NUMBER,                                                                                                                                                                                   
	"RECORD_SOURCE_ID" NUMBER(20,0),                                                                                                                                                                      
	"IS_REVIEW" NUMBER(*,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                    
	"REVIEW_USERS" NVARCHAR2(1000),                                                                                                                                                                       
	"REASON_FOR_REFUSAL" NVARCHAR2(1024),                                                                                                                                                                 
	"REAL_REVIEW_USER" VARCHAR2(100),                                                                                                                                                                     
	 PRIMARY KEY ("RECORD_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                  
   ) ;                                                                                                                                                                                                 

